-- Focused rollback-only local invitation tests. Tokens remain in temporary test state.
begin;
set local search_path=public,extensions,pg_catalog;
select no_plan();
create temp table invitation_test(label text primary key,data jsonb);
grant select,insert on invitation_test to authenticated;
insert into auth.users(id,email,email_confirmed_at) values
 ('71000000-0000-4000-8000-000000000001','invite-admin@example.invalid',now()),
 ('71000000-0000-4000-8000-000000000002','invite-target@example.invalid',now()),
 ('71000000-0000-4000-8000-000000000003','invite-other@example.invalid',now());
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into wedding_private.weddings(id,owner_user_id,title,city,budget_ceiling_paise)
 values('72000000-0000-4000-8000-000000000001',wedding_private.caller_uid(),'Invitation synthetic wedding','Test city',100000);
insert into wedding_private.ceremonies(wedding_id,title,guest_count) values('72000000-0000-4000-8000-000000000001','Reception',100);
insert into wedding_private.tasks(wedding_id,title) values('72000000-0000-4000-8000-000000000001','Private shared task');
insert into wedding_private.cost_items(wedding_id,title,pricing_basis,fixed_estimate_paise) values('72000000-0000-4000-8000-000000000001','Private finance','FIXED',10000);
update wedding_private.weddings set state='ACTIVE' where id='72000000-0000-4000-8000-000000000001';
select ok(not has_table_privilege('authenticated','wedding_access.invitations','SELECT,INSERT,UPDATE,DELETE'),'No direct client invitation/hash access');
select ok(not pg_has_role('authenticated','wedding_invitation_acceptor','MEMBER'),'Client cannot assume acceptance role');
select ok(not has_schema_privilege('wedding_invitation_acceptor','auth','USAGE'),'Acceptor needs no managed Auth access');
select ok(not r.rolcanlogin and not r.rolbypassrls and not r.rolsuper,'Acceptor role restricted') from pg_roles r where rolname='wedding_invitation_acceptor';
select ok(c.relrowsecurity and c.relforcerowsecurity,'Invitations forced RLS') from pg_class c where oid='wedding_access.invitations'::regclass;
set local role authenticated;
insert into invitation_test values('target',public.invitation_issue('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002'));
select ok((select data->>'token' ~ '^[a-f0-9]{64}$' from invitation_test where label='target'),'CSPRNG token has expected format');
select ok((select (data->>'expires_at')::timestamptz between now()+interval '23 hours 59 minutes' and now()+interval '24 hours 1 minute' from invitation_test where label='target'),'Invitation expires in24 hours');
select ok(not (public.invitation_list('72000000-0000-4000-8000-000000000001')->0 ? 'token_hash'),'Admin list excludes hashes');
select ok(not (public.invitation_list('72000000-0000-4000-8000-000000000001')->0 ? 'token'),'Admin list never repeats raw token');
select throws_ok($$select public.invitation_issue('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000001')$$,'22023',null,'No self invitation/Admin creation');
select throws_ok($$select public.invitation_issue('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002')$$,'23505',null,'Only one pending invitation per recipient');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated","user_metadata":{"recipient_user_id":"71000000-0000-4000-8000-000000000002","role":"Admin"}}',true);
select throws_ok($$select public.invitation_accept((select data->>'token' from invitation_test where label='target'))$$,'42501',null,'Wrong recipient cannot accept with forged metadata');
select throws_ok($$select public.invitation_issue('72000000-0000-4000-8000-000000000001',wedding_private.caller_uid())$$,'42501',null,'Unrelated user cannot issue');
select throws_ok($$select public.invitation_revoke('72000000-0000-4000-8000-000000000001',(select (data->>'id')::uuid from invitation_test where label='target'))$$,'42501',null,'Unrelated user cannot revoke');
select throws_ok($$select public.invitation_list('72000000-0000-4000-8000-000000000001')$$,'42501',null,'Unrelated user cannot list');
select throws_ok($$select token_hash from wedding_access.invitations$$,'42501',null,'Token hash cannot be read directly');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":true}',true);
select throws_ok($$select public.invitation_accept((select data->>'token' from invitation_test where label='target'))$$,'42501',null,'Anonymous Auth identity cannot accept');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.invitation_accept((select data->>'token' from invitation_test where label='target')),'72000000-0000-4000-8000-000000000001'::uuid,'Intended authenticated UUID accepts');
select ok(public.planning_read('72000000-0000-4000-8000-000000000001') is not null,'Accepted Member reads planning');
select is(public.finance_read('72000000-0000-4000-8000-000000000001'),null::jsonb,'Accepted Member cannot read financial snapshot');
select is((select count(*) from public.cost_items where wedding_id='72000000-0000-4000-8000-000000000001'),0::bigint,'Member cannot read costs');
select throws_ok($$update public.tasks set title='Forged' where wedding_id='72000000-0000-4000-8000-000000000001'$$,'42501',null,'Member remains read only');
select throws_ok($$select public.invitation_accept((select data->>'token' from invitation_test where label='target'))$$,'42501',null,'Consumed token cannot be reused');
select throws_ok($$select public.invitation_issue('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003')$$,'42501',null,'Member cannot issue invitations');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into invitation_test values('expired',public.invitation_issue('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003'));
reset role;
select ok(exists(select 1 from wedding_access.invitations i join invitation_test t on i.id=(t.data->>'id')::uuid where t.label='target' and i.token_hash<>(t.data->>'token') and i.accepted_at is not null),'Only hash stored; successful invitation consumed');
update wedding_access.invitations set created_at=now()-interval '2 days',expires_at=now()-interval '1 day' where id=(select (data->>'id')::uuid from invitation_test where label='expired');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.invitation_accept((select data->>'token' from invitation_test where label='expired'))$$,'42501',null,'Expired token rejected');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into invitation_test values('revoked',public.invitation_issue('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003'));
select lives_ok($$select public.invitation_revoke('72000000-0000-4000-8000-000000000001',(select (data->>'id')::uuid from invitation_test where label='revoked'))$$,'Admin revokes pending invitation');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.invitation_accept((select data->>'token' from invitation_test where label='revoked'))$$,'42501',null,'Revoked token rejected');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into invitation_test values('superseded',public.invitation_issue('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003'));
select public.membership_grant('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003');
select public.membership_revoke('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000003');
select ok((public.invitation_list('72000000-0000-4000-8000-000000000001')->3->>'revoked_at') is not null,'Member revocation invalidates earlier pending link');
select public.membership_revoke('72000000-0000-4000-8000-000000000001','71000000-0000-4000-8000-000000000002');
select is((select owner_user_id from public.weddings where id='72000000-0000-4000-8000-000000000001'),'71000000-0000-4000-8000-000000000001'::uuid,'Ownership unchanged');
select ok(public.finance_read('72000000-0000-4000-8000-000000000001') is not null,'Owner finance access preserved');
select set_config('request.jwt.claims','{"sub":"71000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.planning_read('72000000-0000-4000-8000-000000000001'),null::jsonb,'Revoked Member loses planning access');
reset role;
set local role anon;
select throws_ok($$select public.invitation_accept('invalid')$$,'42501',null,'Unauthenticated role cannot accept');
reset role;
select * from finish();
rollback;
